/**
 * Fai$al OS service worker (generated by build/pwa.ts from build/sw-template.js).
 * - Precaches the shell and every app chunk, so the whole OS opens offline.
 * - Caches anything else (the v86 Linux files, WebAssembly) the first time it is used.
 * - A new version waits until every tab is closed: pages that are still open keep
 *   loading app chunks from the version they started with, which the server no longer has.
 */
const VERSION = '__VERSION__';
const PRECACHE = __PRECACHE__;
const CACHE = `faisal-os-${VERSION}`;

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(PRECACHE)));
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith('faisal-os-') && key !== CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin || !url.pathname.startsWith(new URL(self.registration.scope).pathname)) return;

  if (req.mode === 'navigate') {
    // Fresh page when online (it may point at a new version); cached page offline.
    event.respondWith((async () => {
      try {
        const res = await fetch(req);
        if (res.ok) (await caches.open(CACHE)).put('./', res.clone());
        return res;
      } catch {
        return (await caches.match('./', { ignoreSearch: true })) ?? (await caches.match('./index.html')) ?? Response.error();
      }
    })());
    return;
  }

  // Hashed assets never change: cache first, then network (and keep a copy).
  event.respondWith((async () => {
    const hit = await caches.match(req, { ignoreSearch: true });
    if (hit) return hit;
    const res = await fetch(req);
    if (res.ok && res.type === 'basic') (await caches.open(CACHE)).put(req, res.clone());
    return res;
  })());
});
